using System.Collections.Generic;
using Undercurrent.CharacterGen;
using UnityEngine;
using Joint = Undercurrent.CharacterGen.Joint;
using NVector3 = System.Numerics.Vector3;

namespace Undercurrent.Runtime.Presentation
{
    /// <summary>
    /// Procedural human fighter: a continuous skinned body generated by <see cref="HumanBodyGenerator"/> on a real joint
    /// hierarchy. Stylised-realistic placeholder until licensed scanned/sculpted characters are integrated.
    /// Local space: facing +Z, up +Y, character's left is -X.
    /// </summary>
    public sealed class Mannequin
    {
        public const int JointCount = HumanSkeleton.JointCount;

        public readonly Transform Root;
        public readonly Transform[] Joints = new Transform[JointCount];
        public readonly Renderer[] Renderers;
        public readonly HumanSkeleton Skeleton;
        public readonly PoseGrounding Grounding;

        private static readonly Dictionary<string, Mesh> MeshCache = new Dictionary<string, Mesh>();

        private Mannequin(Transform root, HumanSkeleton skeleton, Renderer[] renderers)
        {
            Root = root;
            Skeleton = skeleton;
            Renderers = renderers;
            Grounding = new PoseGrounding(skeleton);
        }

        public Transform this[Joint j] => Joints[(int)j];

        public static Mannequin Build(Transform parent, CharacterLook look)
        {
            var body = look.Appearance.Body.Clone();
            body.Detail = look.Detail;

            var root = new GameObject("Human").transform;
            root.SetParent(parent, false);

            var generated = HumanBodyGenerator.Generate(body);
            var sk = generated.Skeleton;
            var joints = new Transform[JointCount];
            for (int i = 0; i < JointCount; i++)
            {
                var t = new GameObject(((Joint)i).ToString()).transform;
                int p = HumanSkeleton.Parent[i];
                t.SetParent(p < 0 ? root : joints[p], false);
                t.localPosition = ToUnity(sk.LocalOffset(i));
                t.localRotation = Quaternion.identity;
                joints[i] = t;
            }

            var meshGo = new GameObject("Body");
            meshGo.transform.SetParent(root, false);
            var smr = meshGo.AddComponent<SkinnedMeshRenderer>();
            smr.sharedMesh = BuildMesh(generated, joints, root, body);
            smr.bones = joints;
            smr.rootBone = joints[(int)Joint.Hips];
            smr.quality = SkinQuality.Bone2;
            smr.updateWhenOffscreen = false;
            smr.localBounds = new Bounds(new Vector3(0f, 0f, 0f), new Vector3(2.6f, 2.6f, 2.6f));
            smr.sharedMaterials = Materials(look);
            smr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.On;

            var m = new Mannequin(root, sk, new Renderer[] { smr });
            System.Array.Copy(joints, m.Joints, JointCount);
            return m;
        }

        private static Vector3 ToUnity(NVector3 v) => new Vector3(v.X, v.Y, v.Z);

        private static Mesh BuildMesh(HumanMesh g, Transform[] joints, Transform root, BodySpec body)
        {
            // Bind poses relative to the mesh's own transform, captured while the skeleton is in rest pose.
            var bindposes = new Matrix4x4[JointCount];
            var meshSpace = root.localToWorldMatrix;
            for (int i = 0; i < JointCount; i++) bindposes[i] = joints[i].worldToLocalMatrix * meshSpace;

            string key = $"{body.Height:0.000}|{body.Build:0.00}|{body.Female}|{body.Hair}|{body.Beard}|{body.Top}|{body.LongPants}|{body.Shoes}|{body.Detail:0.00}";
            if (MeshCache.TryGetValue(key, out var cached) && cached != null)
            {
                cached.bindposes = bindposes;
                return cached;
            }

            int n = g.Positions.Count;
            var verts = new List<Vector3>(n);
            var normals = new List<Vector3>(n);
            var weights = new BoneWeight[n];
            for (int i = 0; i < n; i++)
            {
                verts.Add(ToUnity(g.Positions[i]));
                normals.Add(ToUnity(g.Normals[i]));
                var w = g.Influences[i];
                weights[i] = new BoneWeight
                {
                    boneIndex0 = w.B0, weight0 = 1f - w.W1,
                    boneIndex1 = w.B1, weight1 = w.W1,
                };
            }
            var mesh = new Mesh { name = "UC_Human" };
            if (n > 65000) mesh.indexFormat = UnityEngine.Rendering.IndexFormat.UInt32;
            mesh.SetVertices(verts);
            mesh.SetNormals(normals);
            mesh.subMeshCount = g.Triangles.Length;
            for (int s = 0; s < g.Triangles.Length; s++) mesh.SetTriangles(g.Triangles[s], s);
            mesh.boneWeights = weights;
            mesh.bindposes = bindposes;
            mesh.RecalculateBounds();
            MeshCache[key] = mesh;
            return mesh;
        }

        private static Material[] Materials(CharacterLook look)
        {
            int count = System.Enum.GetValues(typeof(MaterialSlot)).Length;
            var mats = new Material[count];
            for (int i = 0; i < count; i++)
            {
                switch ((MaterialSlot)i)
                {
                    case MaterialSlot.Skin: mats[i] = VisualAssets.Lit(look.Skin, 0.42f); break;
                    case MaterialSlot.Lips: mats[i] = VisualAssets.Lit(look.Lips, 0.5f); break;
                    case MaterialSlot.EyeWhite: mats[i] = VisualAssets.Lit(new Color(0.9f, 0.88f, 0.85f), 0.85f); break;
                    case MaterialSlot.Iris: mats[i] = VisualAssets.Lit(look.Iris, 0.9f); break;
                    case MaterialSlot.Brow:
                    case MaterialSlot.Hair: mats[i] = VisualAssets.Lit(look.Hair, 0.3f); break;
                    case MaterialSlot.Outfit: mats[i] = VisualAssets.Lit(look.Outfit, 0.18f); break;
                    case MaterialSlot.OutfitTrim: mats[i] = VisualAssets.Lit(look.OutfitTrim, 0.3f); break;
                    case MaterialSlot.Wraps: mats[i] = VisualAssets.Lit(look.Wraps, 0.12f); break;
                    default: mats[i] = VisualAssets.Lit(look.Shoes, 0.5f); break;
                }
            }
            return mats;
        }
    }
}
